6: /**
7:  * UserContextService — Gerencia o contexto pessoal do usuário para RAG.
8:  *
9:  * Indexa e busca no conteúdo do usuário:
10:  * - Notas de estudo
11:  * - Sermões
12:  * - Destaques/highlights
13:  * - Planos de estudo
14:  *
15:  * Quando o usuário faz uma pergunta, o sistema busca no seu próprio conteúdo
16:  * para enriquecer o contexto enviado à IA, gerando respostas personalizadas
17:  * baseadas no que o usuário já estudou.
18:  *
19:  * Isso significa que dois usuários podem fazer a mesma pergunta e receber
20:  * respostas diferentes, baseadas no seu histórico de estudo pessoal.
21:  */
22: 
23: export interface UserDocument {
24:   id: string;
25:   userId: string;
26:   type: 'note' | 'sermon' | 'highlight' | 'study' | 'bookmark';
27:   content: string;
28:   metadata: Record<string, any>;
29:   embedding?: number[];
30:   createdAt: number;
31: }
32: 
33: interface IndexedDocument extends UserDocument {
34:   embedding: number[];
35: }
