37: @Injectable()
38: export class UserContextService implements OnModuleInit {
39:   private readonly logger = new Logger(UserContextService.name);
40:   private redis: Redis | null = null;
41: 
42:   // Índice em memória por usuário (carregado do Redis/DB)
43:   private userIndex = new Map<string, IndexedDocument[]>();
44: 
45:   // Track de documentos já indexados por usuário
46:   private indexedDocIds = new Map<string, Set<string>>();
47: 
48:   private readonly MAX_IN_MEMORY_DOCS_PER_USER = 50;
49:   private readonly MAX_CONTEXT_DOCS = 6;
50: 
51:   constructor(
52:     private prisma: PrismaService,
53:     private embeddingService: EmbeddingService,
54:   ) {
55:     const redisUrl = process.env.REDIS_URL;
56:     if (redisUrl) {
57:       this.redis = new Redis(redisUrl, {
58:         lazyConnect: true,
59:         maxRetriesPerRequest: 1,
60:         enableOfflineQueue: false,
61:       });
62: 
63:       this.redis.on('error', (err) => {
64:         if (this.redis && !this.redis['hasLoggedError']) {
65:           this.logger.warn(
66:             `Redis connection failed (local cache persistence disabled): ${err.message}`,
67:           );
68:           this.redis['hasLoggedError'] = true;
69:         }
70:       });
71:     }
72:   }
73: 
74:   async onModuleInit() {
75:     this.logger.log('Inicializando contexto do usuário...');
76:   }
77: 
78:   /**
79:    * Indexa documentos do usuário (notas, sermões, etc.)
80:    * Implementa Memory Eviction: mantém apenas os últimos N no mapa local (Hot),
81:    * enquanto o pgvector no banco de dados armazena o histórico total (Cold).
82:    */
83:   async indexUserDocuments(
84:     userId: string,
85:     documents: UserDocument[],
86:   ): Promise<{
87:     indexed: number;
88:     skipped: number;
89:     total: number;
90:   }> {
91:     if (!this.indexedDocIds.has(userId)) {
92:       this.indexedDocIds.set(userId, new Set<string>());
93:     }
94:     const userDocIds = this.indexedDocIds.get(userId)!;
95:     const newDocs = documents.filter((d) => !userDocIds.has(d.id));
96: 
97:     if (newDocs.length === 0) {
98:       return {
99:         indexed: 0,
100:         skipped: documents.length,
101:         total: this.getUserDocCount(userId),
102:       };
103:     }
104: 
105:     const texts = newDocs.map((doc) => this.buildDocumentText(doc));
106:     const embeddings = await this.embeddingService.createBatchEmbeddings(texts);
107: 
108:     const existing = this.userIndex.get(userId) || [];
109: 
110:     for (let i = 0; i < newDocs.length; i++) {
111:       const indexedDoc: IndexedDocument = {
112:         ...newDocs[i],
113:         embedding: embeddings[i],
114:       };
115:       existing.push(indexedDoc);
116:       userDocIds.add(newDocs[i].id);
117:     }
118: 
119:     // Memory Eviction: mantém apenas os 50 mais recentes em RAM
120:     if (existing.length > this.MAX_IN_MEMORY_DOCS_PER_USER) {
121:       existing.sort((a, b) => b.createdAt - a.createdAt);
122:       existing.splice(this.MAX_IN_MEMORY_DOCS_PER_USER);
123:     }
124: 
125:     this.userIndex.set(userId, existing);
126: 
127:     // Persiste TODOS no banco (Cold Storage / Scalable Search)
128:     await this.persistToDatabase(userId, newDocs, embeddings);
129: 
130:     return {
131:       indexed: newDocs.length,
132:       skipped: documents.length - newDocs.length,
133:       total: existing.length,
134:     };
135:   }
