137:   /**
138:    * Busca documentos do usuário semanticamente relevantes para uma query.
139:    * Implementa Tiered Storage (SEC-010):
140:    * 1. Busca no Cache em Memória (Hot - documentos recém indexados)
141:    * 2. Busca no Banco de Dados (Cold - pgvector para escala)
142:    */
143:   async searchUserContext(
144:     userId: string,
145:     query: string,
146:     maxResults: number = this.MAX_CONTEXT_DOCS,
147:   ): Promise<{ document: UserDocument; similarity: number }[]> {
148:     const queryEmbedding = await this.embeddingService.createEmbedding(query);
149: 
150:     // 1. Busca em Memória (Tier 1 - Ultrarápido)
151:     const userDocs = this.userIndex.get(userId) || [];
152:     const memoryResults = userDocs.map((doc) => ({
153:       document: doc,
154:       similarity: this.embeddingService.cosineSimilarity(
155:         queryEmbedding,
156:         doc.embedding,
157:       ),
158:     }));
159: 
160:     // 2. Busca no Banco de Dados (Tier 2 - Escalonável)
161:     let dbResults: { document: UserDocument; similarity: number }[] = [];
162:     try {
163:       // Usamos JSON.stringify para garantir que o array vire uma string compatível com o cast de ::vector
164:       const rows = await this.prisma.$queryRaw<any[]>`
165:         SELECT id, type, content, metadata, "createdAt",
166:                1 - (embedding <=> ${JSON.stringify(queryEmbedding)}::vector) as similarity
167:         FROM "UserEmbedding"
168:         WHERE "userId" = ${userId} AND type != 'library_book'
169:         ORDER BY embedding <=> ${JSON.stringify(queryEmbedding)}::vector
170:         LIMIT ${maxResults};
171:       `;
172: 
173:       dbResults = rows.map((r) => ({
174:         document: {
175:           id: r.id,
176:           userId: userId,
