382:     // Nº mínimo de validações independentes para ativar (default 1 no beta;
383:     // subir para 2+ via env quando a base de usuários crescer).
384:     const minVotesRaw = Number(process.env.VALIDATED_QA_MIN_VOTES ?? 1);
385:     const minVotes =
386:       Number.isFinite(minVotesRaw) && minVotesRaw >= 1 ? minVotesRaw : 1;
387: 
388:     try {
389:       const queryEmbedding = await this.embeddingService.createEmbedding(query);
390: 
391:       // Pergunta validada quase idêntica já existe? → conta como VOTO, não duplicata cega
392:       const existing = await this.prisma.$queryRaw<any[]>`
393:         SELECT id, metadata,
394:                1 - (embedding <=> ${JSON.stringify(queryEmbedding)}::vector) as similarity
395:         FROM "UserEmbedding"
396:         WHERE type = 'validated_qa'
397:         ORDER BY embedding <=> ${JSON.stringify(queryEmbedding)}::vector
398:         LIMIT 1;
399:       `;
400: 
401:       if (existing.length > 0 && existing[0].similarity >= 0.95) {
402:         const row = existing[0];
403:         const meta =
404:           typeof row.metadata === 'string'
405:             ? JSON.parse(row.metadata)
406:             : row.metadata || {};
407:         const votes: string[] = Array.isArray(meta.votes)
408:           ? meta.votes
409:           : [meta.validatedBy].filter(Boolean);
410: 
411:         if (votes.includes(validatedBy)) {
412:           // Mesmo usuário não vota duas vezes na mesma pergunta
413:           return { promoted: false, reason: 'duplicate', votes: votes.length };
414:         }
415: 
416:         votes.push(validatedBy);
417:         const status = votes.length >= minVotes ? 'active' : 'pending';
418:         const newMeta = { ...meta, votes, status };
419: 
420:         await this.prisma.$executeRaw`
421:           UPDATE "UserEmbedding"
422:           SET metadata = ${JSON.stringify(newMeta)}::jsonb
423:           WHERE id = ${row.id};
424:         `;
425:         this.logger.log(
426:           `[Validated QA] Voto de ${validatedBy} (${votes.length}/${minVotes}) → ${status}`,
427:         );
428:         return {
429:           promoted: status === 'active',
430:           reason: status === 'pending' ? 'pending' : undefined,
431:           votes: votes.length,
432:         };
433:       }
434: 
435:       // Primeira validação desta pergunta
436:       const status = 1 >= minVotes ? 'active' : 'pending';
437:       const metadata = {
438:         query,
439:         answer,
440:         validatedBy,
441:         votes: [validatedBy],
442:         status,
443:         validatedAt: new Date().toISOString(),
444:         origin: 'theoai',
445:       };
446: 
447:       await this.prisma.$executeRaw`
448:         INSERT INTO "UserEmbedding" (id, "userId", type, content, metadata, embedding, "createdAt")
449:         VALUES (
450:           gen_random_uuid()::text,
451:           ${validatedBy},
452:           'validated_qa',
453:           ${query},
454:           ${JSON.stringify(metadata)}::jsonb,
455:           ${JSON.stringify(queryEmbedding)}::vector,
456:           NOW()
457:         );
458:       `;
459:       this.logger.log(
460:         `[Validated QA] Registrada por ${validatedBy} (1/${minVotes}) → ${status}`,
461:       );
462:       return {
463:         promoted: status === 'active',
464:         reason: status === 'pending' ? 'pending' : undefined,
465:         votes: 1,
466:       };
467:     } catch (err) {
468:       this.logger.error(
469:         `[Validated QA] Falha na promoção: ${(err as Error).message}`,
470:       );
