123:   for (let i = 0; i < texts.length; i += EMBEDDING_CONCURRENCY) {
124:     const batch = texts.slice(i, i + EMBEDDING_CONCURRENCY);
125:     const batchResults = await Promise.all(
126:       batch.map(async (text) => {
127:         return callWithRetry(async () => {
128:           const res = await ai.models.embedContent({
129:             model: 'gemini-embedding-001',
130:             contents: text,
131:             config: {
132:               taskType: 'RETRIEVAL_DOCUMENT',
133:               outputDimensionality: 768,
134:             },
135:           });
136:           return (res.embeddings?.[0]?.values ?? null) as number[] | null;
137:         }).catch((err) => {
138:           console.error(`  ❌ Falha definitiva no chunk: ${err.message}`);
139:           return null;
140:         });
141:       }),
142:     );
143:     results.push(...batchResults);
144:     if (i + EMBEDDING_CONCURRENCY < texts.length) {
145:       await sleep(THROTTLE_MS);
146:     }
147:   }
148:   return results;
149: }
