157: ) {
158:   const client = await pool.connect();
159:   let inserted = 0;
160:   let skipped = 0;
161:   try {
162:     for (let i = 0; i < chunks.length; i++) {
163:       const text = chunks[i];
164:       const embedding = embeddings[i];
165:       if (!embedding) { skipped++; continue; }
166: 
167:       const chunkId = `gutenberg_${meta.gutenbergId}_chunk_${i}`;
168: 
169:       const existing = await client.query(
170:         `SELECT id FROM "UserEmbedding" WHERE metadata->>'chunkId' = $1 AND "userId" = $2 LIMIT 1`,
171:         [chunkId, ADMIN_USER_ID],
172:       );
173:       if (existing.rowCount! > 0) { skipped++; continue; }
174: 
175:       const embeddingStr = `[${embedding.join(',')}]`;
176:       const metadata = JSON.stringify({
177:         chunkId,
178:         title: meta.title,
179:         author: meta.author,
180:         source: meta.source,
181:         gutenbergId: meta.gutenbergId,
182:         chunkIndex: i,
183:       });
184:       await client.query(
185:         `INSERT INTO "UserEmbedding" ("id","userId","type","content","metadata","embedding","createdAt")
186:          VALUES (gen_random_uuid(), $1, 'book_chunk', $2, $3::jsonb, $4::vector, NOW())`,
187:         [ADMIN_USER_ID, text, metadata, embeddingStr],
188:       );
189:       inserted++;
190:     }
191:   } finally {
192:     client.release();
193:   }
194:   return { inserted, skipped };
